def read_large_file_in_chunks(filepath, chunk_size=10000):
    """Yields chunks instead of loading the entire file into memory at once."""
    with open(filepath) as f:
        chunk = []
        for line in f:
            chunk.append(line)
            if len(chunk) == chunk_size:
                yield chunk
                chunk = []
        if chunk:
            yield chunk

